import sqlite3
import pandas as pd

conn = sqlite3.connect(":memory:")
conn.execute("CREATE TABLE visits (visit_id INTEGER, page TEXT, seconds INTEGER)")
conn.executemany("INSERT INTO visits VALUES (?, ?, ?)", [(1, "home", 90), (2, "pricing", 20), (3, "home", 45), (4, "docs", 300), (5, "pricing", 75), (6, "docs", 30)])

def query_visits(conn, min_seconds):
    return pd.read_sql("SELECT visit_id, page, seconds FROM visits WHERE seconds >= ?", conn, params=(min_seconds,))

def add_minutes(df):
    return df.assign(minutes=df["seconds"] / 60)

def summarise(df):
    out = df.groupby("page", as_index=False).agg(visits=("visit_id", "count"), minutes=("minutes", "sum"))
    return out.assign(minutes=out["minutes"].round(2))

print(query_visits(conn, 30).pipe(add_minutes).pipe(summarise).to_string(index=False))

import sqlite3
import pandas as pd

def query_orders(conn, status):
    return pd.read_sql("SELECT order_id, amount_cents, currency FROM orders WHERE status = ? ORDER BY order_id", conn, params=(status,))

def add_amount(df):
    return df.assign(amount=df["amount_cents"] / 100)

def summarise(df):
    return df.groupby("currency", as_index=False).agg(orders=("order_id", "count"), revenue=("amount", "sum"))

def check_steps():
    conn = sqlite3.connect(":memory:")
    conn.execute("CREATE TABLE orders (order_id INTEGER, amount_cents INTEGER, currency TEXT, status TEXT)")
    conn.executemany("INSERT INTO orders VALUES (?,?,?,?)", [(1, 1000, "EUR", "paid"), (2, 250, "EUR", "paid"), (3, 400, "USD", "paid"), (4, 999, "EUR", "failed"), (5, 100, "USD", "refunded")])
    raw = query_orders(conn, "paid")
    columns = list(raw.columns)
    added = add_amount(raw)
    summary = summarise(added).set_index("currency")
    return [
        "query: " + ("PASS" if len(raw) == 3 else "FAIL"),
        "transform: " + ("PASS" if list(raw.columns) == columns and "amount" in added.columns else "FAIL"),
        "summary: " + ("PASS" if summary.loc["EUR", "revenue"] == 12.5 else "FAIL"),
    ]

for line in check_steps():
    print(line)
